package fpv.campaign;
import arc.*;import arc.files.Fi;import arc.mock.*;import arc.util.*;import fpv.background.*;import mindustry.*;import mindustry.content.*;import mindustry.core.*;import mindustry.io.*;import mindustry.net.*;import java.nio.file.Files;import java.util.Arrays;

/** Real native sector generators and disk saves in a new disposable profile, never owner saves. */
public final class BackgroundCampaignNativeTest {
    static int checks;static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    static void sector(mindustry.type.Sector s){new WorldReloader().begin();Vars.world.loadSector(s);Vars.logic.play();}
    public static void main(String[] args)throws Exception{
        Core.app=new MockApplication();Core.files=new MockFiles();Core.settings=new Settings();Core.settings.setDataDirectory(new Fi(Files.createTempDirectory("m3-background-campaign-").toFile()));Core.settings.setAutosave(false);Core.settings.setJson(JsonIO.json);Core.settings.load();Core.bundle=I18NBundle.createEmptyBundle();Core.audio=new MockAudio();Core.graphics=new MockGraphics();Vars.headless=true;Vars.loadLocales=false;Vars.net=new Net(null);Vars.platform=new Platform(){};Vars.init();Vars.content.createBaseContent();Vars.content.init();Vars.logic=new Logic();Vars.netServer=new NetServer();Vars.netClient=new NetClient();Vars.schematics=new mindustry.game.Schematics();Vars.schematics.load();Time.setDeltaProvider(()->1);
        sector(SectorPresets.groundZero.sector);String first=BackgroundProfiles.mapKey();var style=new BackgroundStyle();style.mode=BackgroundStyle.Mode.CUSTOM;style.customBaseManual=true;style.whole=BackgroundPreset.OCEAN;style.paint(Vars.world.width(),Vars.world.height()).line(-35,64,-35,90,35,.8,BackgroundPaint.Brush.FOREST,0);BackgroundProfiles.apply(style);check(BackgroundProfiles.status().startsWith("Saved"),"campaign art persisted outside native save");long art=BackgroundProfiles.current().fingerprint();
        var save=Vars.saveDirectory.child("disposable-background.msav");SaveIO.save(save);byte[] bytes=save.readBytes();BackgroundProfiles.reload();check(BackgroundProfiles.current().fingerprint()==art,"cold local reload retains art");
        sector(Planets.serpulo.sectors.get(2));check(!BackgroundProfiles.mapKey().equals(first)&&BackgroundProfiles.current().mode==BackgroundStyle.Mode.AUTO,"different campaign sector starts independent Auto profile");var other=new BackgroundStyle();other.mode=BackgroundStyle.Mode.MANUAL;other.whole=BackgroundPreset.ICE;BackgroundProfiles.apply(other);long context=BackgroundProfiles.context();BackgroundProfiles.preview(style);
        SaveIO.load(save,Vars.world.makeSectorContext(SectorPresets.groundZero.sector));Vars.state.set(GameState.State.playing);check(BackgroundProfiles.mapKey().equals(first)&&BackgroundProfiles.current().fingerprint()==art,"real full SaveIO + sector return restore exact local art");BackgroundProfiles.revertPreview(context);check(BackgroundProfiles.current().fingerprint()==art,"old editor close cannot revert a new sector profile");check(Arrays.equals(bytes,save.readBytes()),"background operations never rewrite native save bytes");
        Vars.state.rules.sector=null;Vars.state.map=new mindustry.maps.Map(arc.struct.StringMap.of("name","Custom coast","author","fixture"));String custom=BackgroundProfiles.mapKey();BackgroundProfiles.apply(style);long customArt=BackgroundProfiles.current().fingerprint();SaveIO.save(save);SaveIO.load(save);Vars.state.set(GameState.State.playing);check(BackgroundProfiles.mapKey().equals(custom)&&BackgroundProfiles.current().fingerprint()==customArt,"custom map name/floor identity survives real disk SaveIO including lost author");
        Vars.state.map=new mindustry.maps.Map(arc.struct.StringMap.of("name","Different map","author","fixture"));check(!BackgroundProfiles.mapKey().equals(custom)&&BackgroundProfiles.current().mode==BackgroundStyle.Mode.AUTO,"same dimensions do not leak another named map's paint");
        Vars.state.rules.sector=Planets.erekir.sectors.first();check(!BackgroundProfiles.mapKey().equals(first),"planet identity separates campaign keys");
        System.out.println("BackgroundCampaignNativeTest: "+checks+" actual campaign/custom SaveIO/map switch/old-preview/isolation checks PASS; physical gameplay/network acceptance separate");
    }
}
